function baitaIcon(name) {
  const icon = BAITA_ICONS[name];
  if (!icon) throw new Error("Unknown finalized icon: " + name);
  return `<svg class="icon baita-icon" data-icon="${name}" viewBox="${icon.viewBox}" ${icon.attributes} aria-hidden="true" focusable="false">${icon.body}</svg>`;
}
